//
// The call structure of a native module's load entry, which hands it the directory of its files,
// generated by cbindgen from the operator crate's `crates/ops/src/kernel.rs` (`ops::abi`): do not
// edit.
//
// The assertions at the end state the size and every field offset of each structure as Rust lays it
// out.
//
// `cargo test -p ops` compares this file with the generator's output, and this command writes it:
//
//   UPDATE_EXPECT=1 cargo test -p ops abi::headers

#pragma once

#include <cstddef>
#include <cstdint>
#include "uniserve_abi.h"

/// The call of a native module's load entry ([`crate::LOAD_ENTRY`]): the directory of the module's
/// files, for a module that reads files published beside its library (the cubins a trtllm-gen
/// module launches). Declared to the packages as `uniserve_load_call` (`uniserve_load.h`,
/// generated with its layout asserted: [`crate::abi`]).
struct uniserve_load_call {
  /// The NUL-terminated path of the directory the module's files were published in.
  const char *directory;
  /// The NUL-terminated message the entry writes before it returns a nonzero status.
  char error[UNISERVE_MESSAGE];
};

static_assert(sizeof(uniserve_load_call) == 520, "the operator crate's layout of uniserve_load_call");
static_assert(offsetof(uniserve_load_call, directory) == 0, "the operator crate's layout of uniserve_load_call");
static_assert(offsetof(uniserve_load_call, error) == 8, "the operator crate's layout of uniserve_load_call");
